# 10. OUTLIER ANALYSIS


def outlier_analysis(df):

    print("\n")
    print("=" * 70)
    print("7. OUTLIER ANALYSIS")
    print("=" * 70)

    results = []

    for category, group in df.groupby(
        "Category"
    ):

        prices = group[
            "Price"
        ].dropna()

        if len(prices) == 0:
            continue

        q1 = prices.quantile(0.25)
        q3 = prices.quantile(0.75)

        iqr = q3 - q1

        lower = q1 - 1.5 * iqr
        upper = q3 + 1.5 * iqr

        outliers = (
            (prices < lower) |
            (prices > upper)
        )

        results.append({
            "Category": category,
            "Q1": q1,
            "Q3": q3,
            "IQR": iqr,
            "Lower_Bound": lower,
            "Upper_Bound": upper,
            "Outlier_Count": int(
                outliers.sum()
            )
        })

    outlier_df = pd.DataFrame(
        results
    ).round(2)

    print("\nPrice Outliers by Category:")
    print(outlier_df)

    outlier_df.to_csv(
        os.path.join(
            OUTPUT_FOLDER,
            "price_outliers.csv"
        ),
        index=False
    )

    # 
    # Visualization 10
    # 

    plt.figure(figsize=(11, 6))

    data = (
        outlier_df
        .sort_values(
            "Outlier_Count"
        )
    )

    plt.barh(
        data["Category"],
        data["Outlier_Count"]
    )

    plt.title(
        "Price Outliers by Category (IQR Method)"
    )

    plt.xlabel(
        "Number of Outliers"
    )

    plt.ylabel(
        "Category"
    )

    plt.tight_layout()

    plt.savefig(
        os.path.join(
            OUTPUT_FOLDER,
            "10_price_outliers.png"
        ),
        dpi=300
    )

    plt.show()

    # 
    # Extreme products
    # 

    top_expensive = (
        df.dropna(
            subset=["Price"]
        )
        .sort_values(
            "Price",
            ascending=False
        )
        [
            [
                "Category",
                "Product Name",
                "Price",
                "Original Prices",
                "Discount rates"
            ]
        ]
        .head(20)
    )

    print(
        "\nTop Extreme-Price Products:"
    )

    print(top_expensive)



