# 12. CORRELATION ANALYSIS


def correlation_analysis(df):

    print("\n")
    print("=" * 70)
    print("9. CORRELATION ANALYSIS")
    print("=" * 70)

    possible_columns = [
        "Price",
        "Original Prices",
        "Discount rates",
        "Discount_Amount",
        "Discount_Rate_Calculated",
        "Ratings"
    ]

    numeric_columns = [
        column
        for column in possible_columns
        if column in df.columns
    ]

    corr = df[
        numeric_columns
    ].corr(
        numeric_only=True
    )

    print("\nCorrelation Matrix:")
    print(corr.round(3))

    corr.to_csv(
        os.path.join(
            OUTPUT_FOLDER,
            "correlation_matrix.csv"
        )
    )

    # 
    # Visualization 14
    # 

    plt.figure(figsize=(10, 7))

    sns.heatmap(
        corr,
        annot=True,
        fmt=".2f",
        cmap="coolwarm",
        center=0
    )

    plt.title(
        "Numeric Correlation Matrix"
    )

    plt.tight_layout()

    plt.savefig(
        os.path.join(
            OUTPUT_FOLDER,
            "14_correlation_matrix.png"
        ),
        dpi=300
    )

    plt.show()

    # 
    # Correlation by category
    # 

    print(
        "\nCorrelation by Category:"
    )

    for category, group in df.groupby(
        "Category"
    ):

        available = [
            column
            for column in numeric_columns
            if column in group.columns
        ]

        if len(available) < 2:
            continue

        category_corr = (
            group[available]
            .corr()
            .round(3)
        )

        print(
            f"\n--- {category} ---"
        )

        print(category_corr)



# 13. BRAND ANALYSIS


def brand_analysis(df):

    print("\n")
    print("=" * 70)
    print("10. BRAND ANALYSIS")
    print("=" * 70)

    if "Brand" not in df.columns:

        print(
            "Brand column not available."
        )

        return

    brand_df = df[
        df["Brand"].notna()
    ].copy()

    if brand_df.empty:

        print(
            "No brand data available."
        )

        return

    # 
    # Create normalized brand
    # 

    brand_df["Brand_Normalized"] = (
        brand_df["Brand"]
        .astype(str)
        .str.strip()
        .str.lower()
    )

    # 
    # Brand summary by category
    # 

    brand_summary = (
        brand_df
        .groupby(
            [
                "Category",
                "Brand_Normalized"
            ]
        )
        .agg(

            Product_Count=(
                "Product Name",
                "count"
            ),

            Total_Price=(
                "Price",
                "sum"
            ),

            Total_Original_Price=(
                "Original Prices",
                "sum"
            ),

            Total_Discount=(
                "Discount_Amount",
                "sum"
            ),

            Average_Price=(
                "Price",
                "mean"
            ),

            Average_Discount=(
                "Discount rates",
                "mean"
            )
        )
        .reset_index()
        .round(2)
    )

    print(
        "\nBrand Summary:"
    )

    print(
        brand_summary.head(30)
    )

    brand_summary.to_csv(
        os.path.join(
            OUTPUT_FOLDER,
            "brand_category_summary.csv"
        ),
        index=False
    )

    # 
    # Top brands by product count
    # 

    top_brands = (
        brand_df[
            "Brand_Normalized"
        ]
        .value_counts()
        .head(15)
        .sort_values()
    )

    print(
        "\nTop 15 Brands by Product Count:"
    )

    print(top_brands)

    # 
    # Visualization 15
    # 

    plt.figure(figsize=(10, 7))

    plt.barh(
        top_brands.index,
        top_brands.values
    )

    plt.title(
        "Top 15 Brands by Number of Products"
    )

    plt.xlabel(
        "Number of Products"
    )

    plt.ylabel("Brand")

    plt.tight_layout()

    plt.savefig(
        os.path.join(
            OUTPUT_FOLDER,
            "15_top_brands.png"
        ),
        dpi=300
    )

    plt.show()

    # 
    # Top brands by average discount
    # Minimum 10 products
    # 

    top_discount_brands = (
        brand_df
        .groupby(
            "Brand_Normalized"
        )["Discount rates"]
        .agg(
            [
                "mean",
                "count"
            ]
        )
        .query(
            "count >= 10"
        )
        .sort_values(
            "mean"
        )
        .tail(15)
    )

    print(
        "\nBrands with Highest Average Discount:"
    )

    print(
        top_discount_brands.round(2)
    )

    # 
    # Visualization 16
    # 

    plt.figure(figsize=(10, 7))

    plt.barh(
        top_discount_brands.index,
        top_discount_brands["mean"]
    )

    plt.title(
        "Brands with Highest Average Discount\n"
        "(Minimum 10 Products)"
    )

    plt.xlabel(
        "Average Discount (%)"
    )

    plt.ylabel("Brand")

    plt.tight_layout()

    plt.savefig(
        os.path.join(
            OUTPUT_FOLDER,
            "16_top_discount_brands.png"
        ),
        dpi=300
    )

